/**
 * Pagination. Molded number caps; the current page
 * is a lit accent cap, pressed into the chassis. Composes var(--echo-*).
 */
.echo-pagination {
  display: flex;
  align-items: center;
  /*
   * `inline-flex` with no wrapping made this the only control in the
   * library that could push the DOCUMENT open — 419 > 390 on /docs/pagination,
   * 410 > 390 on /gallery/navigation. Twenty pages of 30px caps is wider than
   * a phone before you count the prev/next steps, and nothing let it fold.
   */
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--echo-space-3);
  max-width: 100%;
}

.echo-pagination__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--echo-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.echo-pagination__page,
.echo-pagination__step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-width: var(--echo-control-compact);
  height: var(--echo-control-compact);
  padding: 0 var(--echo-space-4);
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-xs);
  font-weight: var(--echo-weight-semibold, 600);
  font-variant-numeric: tabular-nums;
  line-height: var(--echo-leading-none, 1);
  color: var(--echo-text);
  /* The HardwareButton neutral cap, with a 2px side wall at this size. */
  background: linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    var(--echo-cap) 40%,
    var(--echo-cap) 62%,
    var(--echo-cap-shadow) 100%
  );
  box-shadow:
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.42 * var(--echo-gloss, 1))),
    inset 0 -2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.5 * var(--echo-shade, 1) * 100%), transparent),
    0 calc(2px + 1px * var(--lift, 0) - 2px * var(--press, 0)) 0 var(--echo-seam),
    0 calc(5px + 3px * var(--lift, 0) - 3px * var(--press, 0))
      calc(9px + 5px * var(--lift, 0) - 5px * var(--press, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.5 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  /* The press is useCapPhysics's (pagination.tsx): lift, lean, travel. */
  position: relative;
  overflow: hidden;
  will-change: transform;
}

.echo-pagination__step {
  min-width: var(--echo-control-compact);
  padding: 0;
  color: var(--echo-text-dim);
}

.echo-pagination__step svg {
  width: var(--echo-icon-md, 16px);
  height: var(--echo-icon-md, 16px);
}

/* Previous and next point the way the page reads: flipped in right-to-left. */
.echo-pagination__step:dir(rtl) svg {
  transform: scaleX(-1);
}

.echo-pagination__page:focus-visible,
.echo-pagination__step:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

/*
 * The current page is lit and seated — it is where you are, not somewhere to
 * go. Lit with the Record button's cap and its cream legend: the library has
 * ONE lit accent. This used to be a lighter pastel fill with dark digits and a
 * halo, a second shade that belonged to nothing else.
 */
.echo-pagination__page[data-current] {
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1))),
    inset 0 -2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.3 * var(--echo-shade, 1) * 100%), transparent),
    0 1px 0 var(--echo-accent-6),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-pagination__page[data-current]:focus-visible {
  /* Seated like the current page, ringed like focus. Without this rule the
     current page's box-shadow, declared later, replaced the ring (BUG-4). */
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1))),
    inset 0 -2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.3 * var(--echo-shade, 1) * 100%), transparent),
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow));
}

/* Landing on a page lights it: a flash of the key light blooms out from the
   middle of the cap and fades, the way the lit cap swells into place. */
.echo-pagination__page[data-current]::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    circle,
    rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1))) 0%,
    transparent 70%
  );
  opacity: 0;
  animation: echo-page-light var(--echo-duration-pop) var(--echo-ease-swap);
  pointer-events: none;
}
/* It blooms to the cap's own edge and no further: past it, the cap scrolled
   sideways inside itself while it played (BUG-85). */
@keyframes echo-page-light {
  from {
    opacity: 1;
    transform: scale(0.2);
  }
  to {
    opacity: 0;
    transform: scale(1);
  }
}

.echo-pagination__step[disabled] {
  opacity: 0.4;
  cursor: default;
}

.echo-pagination__step[disabled]:active {
  transform: none;
}

.echo-pagination__gap {
  display: inline-flex;
  align-items: flex-end;
  justify-content: center;
  min-width: 20px;
  height: 30px;
  padding-bottom: var(--echo-space-3);
  color: var(--echo-text-dim);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-xs);
  line-height: var(--echo-leading-none, 1);
}

@media (prefers-reduced-motion: reduce) {
  .echo-pagination__page,
  .echo-pagination__step {
    transition: none;
  }
  .echo-pagination__page[data-current]::after {
    animation: none;
  }
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the other
 * threshold: the 44px both platform guidelines use, which is about a
 * fingertip rather than about conformance.
 *
 * Gated on `@media (pointer: coarse)` so the desktop rendering does not move
 * — these are "passing AA but under the
 * platform guideline", not broken. Pagination is first among them because
 * people tap it repeatedly, which is exactly when a 30px target starts
 * costing mis-taps.
 */
@media (pointer: coarse) {
  .echo-pagination__page,
  .echo-pagination__step {
    min-width: 44px;
    height: 44px;
  }
}

/**
 * The page window. Pure arithmetic, kept out of the
 * component so the interesting part — where the gaps fall — is unit-testable
 * without a DOM.
 *
 * The rules: the first and last page are always reachable, the current page
 * always sits inside a run of `siblings` on each side, and the width of the
 * output never changes as you page through. That last one is why the boundary
 * cases expand the run instead of just dropping a gap — a control that
 * reflows under the cursor is how you misclick.
 */

/** A gap stands in for pages that are not currently reachable in one click. */
export const GAP = "gap" as const;

export type PageSlot = number | typeof GAP;

export interface PaginationRangeOptions {
  /** 1-based current page. */
  page: number;
  /** Total number of pages. */
  count: number;
  /** Pages shown either side of the current one. Default 1. */
  siblings?: number;
}

export function paginationRange({
  page,
  count,
  siblings = 1,
}: PaginationRangeOptions): PageSlot[] {
  if (!Number.isFinite(count) || count <= 0) return [];

  const clampedPage = Math.min(Math.max(Math.trunc(page), 1), count);
  const sib = Math.max(0, Math.trunc(siblings));

  // first + last + current + 2 gaps + the two sibling runs. Below this there
  // is nothing to elide, so show every page.
  const slotsWhenElided = sib * 2 + 5;
  if (count <= slotsWhenElided) {
    return Array.from({ length: count }, (_, i) => i + 1);
  }

  const left = Math.max(clampedPage - sib, 1);
  const right = Math.min(clampedPage + sib, count);

  // A gap that hides exactly one page is a lie that costs a click, so elide
  // only where at least two pages are actually hidden. left > 3 leaves pages
  // 2..3 behind the gap at minimum; the mirror holds on the right.
  const showLeftGap = left > 3;
  const showRightGap = right < count - 2;

  if (!showLeftGap && showRightGap) {
    // Pinned near the start: grow the head run to keep the width constant.
    const headLength = slotsWhenElided - 2;
    return [...upTo(headLength), GAP, count];
  }

  if (showLeftGap && !showRightGap) {
    const tailLength = slotsWhenElided - 2;
    return [1, GAP, ...from(count - tailLength + 1, count)];
  }

  if (showLeftGap && showRightGap) {
    return [1, GAP, ...from(left, right), GAP, count];
  }

  return Array.from({ length: count }, (_, i) => i + 1);
}

const upTo = (n: number): number[] => Array.from({ length: n }, (_, i) => i + 1);

const from = (start: number, end: number): number[] =>
  Array.from({ length: end - start + 1 }, (_, i) => start + i);

"use client";

/**
 * Pagination. A row of molded number caps with the
 * current page lit, wrapped in a labelled nav.
 *
 * The window arithmetic lives in range.ts so it can be tested without a DOM;
 * this file is the skin and the semantics.
 *
 * Every number is a molded cap with the library's press (useCapPhysics): it
 * rises and leans on hover, travels onto its seam, springs back. The page you
 * land on lights up — the lit cap blooms into it.
 */
import type { ButtonHTMLAttributes, HTMLAttributes } from "react";
import { useCapPhysics } from "echo-ui-core/tactile";
import { paginationRange, GAP } from "./range";
import "./pagination.css";

export interface PaginationProps extends Omit<HTMLAttributes<HTMLElement>, "onChange"> {
  /** 1-based current page. */
  page: number;
  /** Total number of pages. */
  count: number;
  onPageChange: (page: number) => void;
  /** Pages shown either side of the current one. Default 1. */
  siblings?: number;
  /** Name for the nav landmark. Default "Pagination". */
  label?: string;
  /** Accessible name for the previous control. Default "Previous page". */
  previousLabel?: string;
  /** Accessible name for the next control. Default "Next page". */
  nextLabel?: string;
}

export function Pagination({
  page,
  count,
  onPageChange,
  siblings = 1,
  label = "Pagination",
  previousLabel = "Previous page",
  nextLabel = "Next page",
  className,
  ...rest
}: PaginationProps) {
  const slots = paginationRange({ page, count, siblings });
  if (slots.length === 0) return null;

  return (
    <nav
      className={["echo-pagination", className].filter(Boolean).join(" ")}
      aria-label={label}
      {...rest}
    >
      <Cap
        className="echo-pagination__step"
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
        aria-label={previousLabel}
      >
        <Chevron direction="left" />
      </Cap>

      <ol className="echo-pagination__list">
        {slots.map((slot, i) =>
          slot === GAP ? (
            // Not a control: it names nothing and does nothing. Announcing
            // "ellipsis" between two page numbers is noise.
            <li key={`gap-${i}`} className="echo-pagination__gap" aria-hidden="true">
              …
            </li>
          ) : (
            <li key={slot}>
              <Cap
                className="echo-pagination__page"
                onClick={() => onPageChange(slot)}
                aria-label={`Page ${slot}`}
                aria-current={slot === page ? "page" : undefined}
                data-current={slot === page ? "" : undefined}
              >
                {slot}
              </Cap>
            </li>
          ),
        )}
      </ol>

      <Cap
        className="echo-pagination__step"
        onClick={() => onPageChange(page + 1)}
        disabled={page >= count}
        aria-label={nextLabel}
      >
        <Chevron direction="right" />
      </Cap>
    </nav>
  );
}

/* A cap you can press: the library's molded-cap physics on a plain button. */
function Cap({ children, onPointerDown, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) {
  const cap = useCapPhysics<HTMLButtonElement>({ travel: 2, tilt: 7 });
  return (
    <button
      ref={cap.ref}
      type="button"
      {...cap.handlers}
      {...props}
      onPointerDown={(e) => {
        onPointerDown?.(e);
        cap.handlers.onPointerDown?.(e);
      }}
    >
      {children}
    </button>
  );
}

function Chevron({ direction }: { direction: "left" | "right" }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
      <path
        d={direction === "left" ? "M15 6l-6 6 6 6" : "M9 6l6 6-6 6"}
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export { Pagination } from "./pagination";
export type { PaginationProps } from "./pagination";
export { paginationRange, GAP } from "./range";
export type { PageSlot, PaginationRangeOptions } from "./range";
